import{_ as i,o as l,c as o,ag as a}from"./chunks/framework.IxO3mcwW.js";const e="/getbiji-docs/images/link-01.png",s="/getbiji-docs/images/link-02.png",r="/getbiji-docs/images/link-03.png",u="/getbiji-docs/images/link-04.png",c="/getbiji-docs/images/link-05.png",d="/getbiji-docs/images/link-06.png",g=JSON.parse('{"title":"链接一键记","description":"","frontmatter":{},"headers":[],"relativePath":"capture/link.md","filePath":"capture/link.md","lastUpdated":1773147350000}'),n={name:"capture/link.md"};function p(q,t,h,m,x,b){return l(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="链接一键记" tabindex="-1">链接一键记 <a class="header-anchor" href="#链接一键记" aria-label="Permalink to &quot;链接一键记&quot;">​</a></h1><blockquote><p>粘贴链接，AI 帮你提取精华</p></blockquote><p>支持多种平台链接，AI 自动读取内容并总结重点。</p><h2 id="支持的链接类型" tabindex="-1">支持的链接类型 <a class="header-anchor" href="#支持的链接类型" aria-label="Permalink to &quot;支持的链接类型&quot;">​</a></h2><ul><li><strong>图文链接</strong>：微信公众号文章、小红书图文、公开免费网站等</li><li><strong>视频链接</strong>：抖音短视频、B站视频、小红书视频、得到直播回放（需要使用得到App中的分享链接）等</li></ul><h2 id="粘贴公众号文章链接" tabindex="-1">粘贴公众号文章链接 <a class="header-anchor" href="#粘贴公众号文章链接" aria-label="Permalink to &quot;粘贴公众号文章链接&quot;">​</a></h2><ol><li>点击一篇公众号文章，在右上角...中选择复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>粘贴链接后，可以在链接下方添加补充信息和要求，比如&quot;整理 xxx 方面的内容&quot;</li><li>最后，点击&quot;确定&quot;，AI 会读取文章内容并帮你记录总结重点信息</li></ol><div class="tip custom-block"><p class="custom-block-title">图片理解</p><p>若链接中包含多张图片，AI可理解到10张图，且图片理解的能力也会随AI能力的发展逐步增强</p></div><h2 id="粘贴抖音短视频链接" tabindex="-1">粘贴抖音短视频链接 <a class="header-anchor" href="#粘贴抖音短视频链接" aria-label="Permalink to &quot;粘贴抖音短视频链接&quot;">​</a></h2><ol><li>点开一个抖音短视频，在右下角点击分享按钮，选择&quot;分享链接&quot;，然后复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>粘贴链接后，AI 会自动提取其中的 url，同时可以在链接下方添加补充信息和要求，比如&quot;整理 xxx 方面的内容&quot;</li><li>最后，点击&quot;确定&quot;，AI 会读取短视频内容并帮你记录总结重点信息</li></ol><h2 id="粘贴小红书图文-短视频链接" tabindex="-1">粘贴小红书图文/短视频链接 <a class="header-anchor" href="#粘贴小红书图文-短视频链接" aria-label="Permalink to &quot;粘贴小红书图文/短视频链接&quot;">​</a></h2><ol><li>点开一个小红书图文/短视频，在点击分享按钮，然后复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>粘贴链接后，可以在链接下方添加补充信息和要求，比如&quot;整理 xxx 方面的内容&quot;</li></ol><div class="tip custom-block"><p class="custom-block-title">图片文字识别</p><p>如果图片中有文字，也会识别图片中的文字，并进行整理，同时会把图片也保存下来</p></div><ol start="4"><li>最后，点击&quot;确定&quot;，AI 会读取图文/短视频内容并帮你记录总结重点信息</li></ol><h2 id="粘贴-b-站视频链接" tabindex="-1">粘贴 B 站视频链接 <a class="header-anchor" href="#粘贴-b-站视频链接" aria-label="Permalink to &quot;粘贴 B 站视频链接&quot;">​</a></h2><ol><li>点开一个 B 站视频，再点击分享按钮，然后复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>粘贴链接后，可以在链接下方添加补充信息和要求，比如&quot;整理 xxx 方面的内容&quot;</li><li>最后，点击&quot;确定&quot;，AI 会读取短视频内容并帮你记录总结重点信息</li></ol><div class="warning custom-block"><p class="custom-block-title">温馨提醒</p><p>如果视频时长过长（如2小时），AI 处理等待时间会较长，可以先收起处理页面，继续进行其他操作，AI 依然会在后台继续处理。</p></div><h2 id="粘贴得到直播回放链接" tabindex="-1">粘贴得到直播回放链接 <a class="header-anchor" href="#粘贴得到直播回放链接" aria-label="Permalink to &quot;粘贴得到直播回放链接&quot;">​</a></h2><ol><li>在得到APP内选择一场公开直播回放，再点击分享按钮，然后复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>粘贴链接后，可以在链接下方添加补充信息和要求，比如&quot;整理 xxx 方面的内容&quot;</li><li>最后，点击&quot;确定&quot;，AI 会读取直播回放内容，并帮你记录总结重点内容、章节纪要</li></ol><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+e+'" alt="粘贴链接入口" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="输入链接" style="width:180px;border-radius:8px;"><img src="'+r+'" alt="添加要求" style="width:180px;border-radius:8px;"><img src="'+u+'" alt="AI处理中" style="width:180px;border-radius:8px;"><img src="'+c+'" alt="总结结果" style="width:180px;border-radius:8px;"><img src="'+d+'" alt="笔记详情" style="width:180px;border-radius:8px;"></div>',21)])])}const k=i(n,[["render",p]]);export{g as __pageData,k as default};
